class Solution {
    public:
        string lexPalindromicPermutation(string s, string target) {
                int n = s.length();
                        vector<int> count(26, 0);
                                for(char c : s) {
                                            count[c - 'a']++;
                                                    }
                                                            
                                                                    int odd_count = 0;
                                                                            char mid_char = 0;
                                                                                    for(int i = 0; i < 26; i++) {
                                                                                                if(count[i] % 2 != 0) {
                                                                                                                odd_count++;
                                                                                                                                mid_char = i + 'a';
                                                                                                                                            }
                                                                                                                                                    }
                                                                                                                                                            // If more than 1 character has an odd frequency, a palindrome is impossible
                                                                                                                                                                    if(odd_count > 1) return "";
                                                                                                                                                                            
                                                                                                                                                                                    // Build the available character pool for the first half of the palindrome
                                                                                                                                                                                            string pool = "";
                                                                                                                                                                                                    for(int i = 0; i < 26; i++) {
                                                                                                                                                                                                                for(int j = 0; j < count[i] / 2; j++) {
                                                                                                                                                                                                                                pool += (char)(i + 'a');
                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                    int m = n / 2;
                                                                                                                                                                                                                                                                            string target_prefix = target.substr(0, m);
                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                            // Step 1: Check if we can exactly form target's first half
                                                                                                                                                                                                                                                                                                    string exact_prefix = "";
                                                                                                                                                                                                                                                                                                            vector<int> avail_exact(26, 0);
                                                                                                                                                                                                                                                                                                                    for(char c : pool) avail_exact[c - 'a']++;
                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                    bool can_form_exact = true;
                                                                                                                                                                                                                                                                                                                                            for(char c : target_prefix) {
                                                                                                                                                                                                                                                                                                                                                        if(avail_exact[c - 'a'] > 0) {
                                                                                                                                                                                                                                                                                                                                                                        avail_exact[c - 'a']--;
                                                                                                                                                                                                                                                                                                                                                                                        exact_prefix += c;
                                                                                                                                                                                                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                                                                                                                                                                                                    can_form_exact = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                    break;
                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if(can_form_exact) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    string palindrome = exact_prefix;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if(n % 2 != 0) palindrome += mid_char;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            string rev = exact_prefix;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        reverse(rev.begin(), rev.end());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    palindrome += rev;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // If an exact prefix match produces a string strictly greater, it's the minimal possible
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if(palindrome > target) return palindrome;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Step 2: Find the smallest permutation of the pool strictly greater than target_prefix
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        for(int i = m - 1; i >= 0; i--) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    vector<int> avail(26, 0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                for(char c : pool) avail[c - 'a']++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Verify if we have the characters to exactly match up to index i-1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    bool can_match = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                for(int j = 0; j < i; j++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if(avail[target_prefix[j] - 'a'] > 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    avail[target_prefix[j] - 'a']--;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        can_match = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            break;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if(!can_match) continue;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Look for the smallest available character strictly greater than target_prefix[i]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    char best_c = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                for(int c = target_prefix[i] - 'a' + 1; c < 26; c++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if(avail[c] > 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    best_c = c + 'a';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        avail[c]--;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            break;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // If we found a valid character for divergence, construct the rest of the string
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if(best_c != 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            string prefix = target_prefix.substr(0, i) + best_c;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // Append all remaining available characters in alphabetical order
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            for(int c = 0; c < 26; c++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                while(avail[c] > 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        prefix += (char)(c + 'a');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                avail[c]--;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Construct and return the full palindrome
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    string palindrome = prefix;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if(n % 2 != 0) palindrome += mid_char;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    string rev = prefix;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    reverse(rev.begin(), rev.end());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    palindrome += rev;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return palindrome;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // If no configuration is strictly greater than target, return an empty string
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    };
